<script lang="ts">
	import ContentLayout from '$components/ContentLayout.svelte'; import Header from '$components/Header.svelte'; const presets = ['#FFB86C', '#FF7F50', '#FFCBA4', '#F0F8FF', '#E0FFFF', '#87CEEB', '#acdb00', '#0078d4', '#FF00FF', '#E6E6FA', '#98FF98', '#FFE4E1']; let color = $state('#aabbcc'); let message = $state(''); async function send(action: string, value: string) { message = 'Sending...'; const response = await fetch('/lamp/control', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ action, value }) }); message = response.ok ? 'Sent' : await response.text(); }
</script>
<svelte:head><title>Lamp :: janigowski.dev</title></svelte:head><ContentLayout><Header title="Background Lamp" description="You can control my background lamp here. If you want to see the effect just contact me to have a video call and see the colors flowing." /><div class="grid gap-6 md:grid-cols-3"><section class="rounded-xl bg-zinc-900/60 p-6"><h2 class="mb-4 text-lg font-semibold">Power</h2><div class="grid grid-cols-2 gap-3"><button class="rounded bg-brand-lime/20 px-4 py-2 text-brand-lime" onclick={() => send('turn', 'on')}>Turn On</button><button class="rounded bg-zinc-800 px-4 py-2 text-zinc-300" onclick={() => send('turn', 'off')}>Turn Off</button></div></section><section class="rounded-xl bg-zinc-900/60 p-6"><h2 class="mb-4 text-lg font-semibold">Presets</h2><div class="grid grid-cols-3 gap-3">{#each presets as preset}<button class="h-10 rounded border border-white/10" style={`background:${preset}`} aria-label={preset} onclick={() => send('color', preset)}></button>{/each}</div></section><section class="rounded-xl bg-zinc-900/60 p-6"><h2 class="mb-4 text-lg font-semibold">Custom Color</h2><input type="color" bind:value={color} class="h-16 w-full" onchange={() => send('color', color)} /></section></div>{#if message}<p class="text-zinc-400">{message}</p>{/if}<p><a href="/api/hue-login" class="text-brand-lime">Authorize Hue</a></p></ContentLayout>
